insert into public.i18n (k, src, en) values
  ($t$4c039e4a87d62435868706c2b1f0761554c86d599d4794764eb359d9e5bb84e1$t$, $t$نظام إدارة الطوابير (QMS)$t$, $t$Queue Management System (QMS)$t$),
  ($t$078f7d8fca1ed7e7a96abe3caa880a8ec902583f5c30dd57f862c865e5f66a5d$t$, $t$توريد وتركيب وتشغيل نظام إدارة الطوابير: أجهزة إصدار التذاكر، وشاشات العرض الرئيسية وشاشات النوافذ والعيادات، ولوحات الطلب لمقدمي الخدمة، والنداء الصوتي، والخادم والبرمجيات والتقارير، والربط بأنظمة المواعيد المعتمدة لدى التجمع عند الطلب؛ وتلتزم الشاشات بمعيار التجمع للشاشات الرقمية. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$, $t$Supply, install and commission a queue management system: ticket dispensers, main display screens and counter and clinic displays, service-provider call keypads, audio calling, server, software and reports, and integration with the Cluster appointment systems on request; displays shall comply with the Cluster digital signage standard. Including everything required to complete the works fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
  ($t$eca9588c3b3df3dabb49555f894388bfc1fc75c43a03667b330ce955aec0b9d0$t$, $t$نظام إدارة الطوابير (SOW 28.4.1 — اختياري في نطاق العمل، وأُدرج إلزامياً بقرار رئيس قسم المشاريع).$t$, $t$Queue management system (SOW 28.4.1 — optional in the SOW, included as mandatory by decision of the Head of Projects).$t$),
  ($t$ad7689feb001c3db60c70a0cb5b9399bbfa07a4511f612b1d45f829d293951fc$t$, $t$الشاشات الرقمية$t$, $t$Digital Signage$t$),
  ($t$9094e85700d168b623048ad52ecbbd74c66d52a406745b96cd6960d34b04ab5c$t$, $t$توريد وتركيب وتشغيل شاشات العرض الرقمية بالأحجام والمواقع المحددة وفق معيار تجمع الأحساء الصحي للشاشات الرقمية AAHC-FM-STD-DIGITAL-SIGNAGE-001: شاشات عرض تجارية مصممة للتشغيل المتواصل (Samsung QMC أو ما يعادلها المعتمد، وQHC للمناطق عالية الإضاءة) بدقة 4K UHD كحد أدنى، ولا يُقبل التلفزيون المنزلي في المناطق العامة؛ وربط شاشات المناطق العامة بمنصة Navori بمشغّل مدمج أو خارجي؛ ومقبسان كهربائيان خلف كل شاشة (أحدهما على الطوارئ أو UPS حيث أمكن) ونقطة شبكة سلكية RJ45؛ وإخفاء جميع الكابلات؛ والمقاسات وارتفاعات التركيب حسب جداول المعيار. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$, $t$Supply, install and commission digital signage displays in the sizes and locations specified per the Al-Ahsa Health Cluster digital signage standard AAHC-FM-STD-DIGITAL-SIGNAGE-001: commercial displays designed for continuous operation (Samsung QMC or approved equal, and QHC for high-brightness areas) with minimum 4K UHD resolution, no consumer televisions in public areas; public-area displays connected to the Navori platform with built-in or external player; two power sockets behind each display (one on emergency or UPS where possible) and a wired RJ45 network point; all cables concealed; and sizes and mounting heights per the standard's tables. Including everything required to complete the works fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
  ($t$232f87f46154526f2234f7d09442a9b7d598e3bdd37b873e05a78e852d09f8d4$t$, $t$الشاشات الرقمية (SOW Digital signages — اختياري في نطاق العمل، وأُدرج إلزامياً بقرار رئيس قسم المشاريع).$t$, $t$Digital signage (SOW Digital signages — optional in the SOW, included as mandatory by decision of the Head of Projects).$t$),
  ($t$8ab068b69053c124b4d6811171208c1f95eaaf19942e9254af5712e7c0446506$t$, $t$التجهيزات الكهربائية المسبقة لغرفة الأشعة$t$, $t$Electrical Pre-Installation for the X-ray Room$t$),
  ($t$51d2cc9ad782b51448bc43e170ed3494198fcd99931e2692124f1103881b026e$t$, $t$تنفيذ التجهيزات الكهربائية المسبقة لجهاز الأشعة حسب متطلبات الموقع (Site Requirements) الصادرة من مورد الجهاز المعتمد: لوحة التغذية المخصصة بقاطعها وسعتها، ومفتاح الفصل الطارئ، والمجاري والقنوات الأرضية والسقفية للكابلات، ونقاط الشبكة، ومصباح التحذير عند المدخل وربطه بالجهاز؛ بالتنسيق مع قسم التجهيزات الطبية قبل التنفيذ. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$, $t$Carry out the electrical pre-installation for the X-ray unit per the site requirements issued by the approved equipment supplier: dedicated supply panel with its breaker and rating, emergency stop switch, floor and ceiling cable ducts and trunking, network points, and the warning light at the entrance linked to the unit; in coordination with the Medical Equipment section before execution. Including everything required to complete the works fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
  ($t$2b21cae00edcdc7ac2838b47ade7fb7a6f986f94634dea26d4bc0b6e091dd325$t$, $t$التجهيزات الكهربائية المسبقة لغرفة الأشعة (SOW 29 — اختياري في نطاق العمل، وأُدرج إلزامياً بقرار رئيس قسم المشاريع).$t$, $t$Electrical pre-installation for the X-ray room (SOW 29 — optional in the SOW, included as mandatory by decision of the Head of Projects).$t$)
